var builder = DistributedApplication.CreateBuilder(args);

// Generated once per PC and stored in this project's user secrets, so tokens stay valid between runs.
var jwtKey = builder.AddParameter("jwt-key",
    new GenerateParameterDefault { MinLength = 64, Special = false },
    secret: true, persist: true);

// The Postgres password is generated by Aspire and stored in this project's user secrets.
var postgres = builder.AddPostgres("postgres")
    .WithImageTag("17")
    .WithDataVolume()
    .WithLifetime(ContainerLifetime.Persistent)
    .WithPgAdmin();

var database = postgres.AddDatabase("vakantiepark");

var api = builder.AddProject<Projects.Vakantiepark_API>("api")
    .WithReference(database)
    .WithEnvironment("JWT__Key", jwtKey)
    .WaitFor(database);

builder.AddProject<Projects.Vakantiepark_UI>("ui")
    .WaitFor(api);

builder.Build().Run();
